#[derive(Clone, Copy, Debug)]
pub struct Plan { pub regs: &'static [Val], pub local: Val, pub printf: Option<(&'static str, &'static [Val])> }

/// A case's plans: one, or two chosen by whether argument 0xc is greater than 1.
#[derive(Clone, Copy, Debug)]
pub enum Choice { One(&'static Plan), IfArgGt1(&'static Plan, &'static Plan) }

